void InitializeFFmpegVideoDecodeEngine(MessageLoop* message_loop,
                                       VideoDecodeEngine::EventHandler* event_handler,
                                       VideoDecodeContext* context,
                                       const VideoDecoderConfig& config) {
    AVCodecContext* codec_context = avcodec_alloc_context3(NULL);
    if (!codec_context) {
        // Handle error - unable to allocate codec context
        return;
    }

    // Setup codec context with configuration from 'config'
    // Example: codec_context->width = config.width;
    // Example: codec_context->height = config.height;
    // ... similar assignments for other configuration parameters ...

    codec_context->thread_count = 4;  // Setup decoding threading

    // Setup buffer pool for output frames
    AVBufferPool* buffer_pool = av_buffer_pool_init2(
        sizeof(AVFrame),
        NULL,
        avcodec_alloc_frame,
        avcodec_free_frame,
        NULL, NULL);
    if (!buffer_pool) {
        avcodec_free_context(&codec_context);
        // Handle error - unable to allocate buffer pool
        return;
    }

    // Handle codec-specific configurations
    // This could include setting pixel formats, time bases, etc.
    codec_context->pix_fmt = AV_PIX_FMT_YUV420P;
    codec_context->time_base = (AVRational){1, 30};  // Example time base

    // Enable error detection
    codec_context->error_detection = AV_EF_CRCCHECK;

    // Initialize codec
    int result = avcodec_open2(codec_context, avcodec_find_decoder(AV_CODEC_ID_H264), NULL);
    if (result < 0) {
        av_buffer_pool_uninit(&buffer_pool);
        avcodec_free_context(&codec_context);
        // Handle error - failed to open codec
        return;
    }

    // Assign codec context and buffer pool to the context object
    context->codec_context = codec_context;
    context->buffer_pool = buffer_pool;

    // Notify event handler that initialization is complete
    if (event_handler && event_handler->on_engine_initialized) {
        event_handler->on_engine_initialized(message_loop, context);
    }
}

void FFmpegVideoDecodeEngineInitialize(MessageLoop* message_loop, VideoDecodeEngine::EventHandler* event_handler, VideoDecodeContext* context, const VideoDecoderConfig& config) {
    AVCodecContext* codec_context = avcodec_alloc_context3(NULL);
    if (!codec_context) {
        // Handle error
        return;
    }

    // Configure codec context based on config
    codec_context->thread_count = 4; // Example of setting up threading

    // Setup codec-specific configurations
    if (avcodec_open2(codec_context, NULL, NULL) < 0) {
        // Handle error
        avcodec_free_context(&codec_context);
        return;
    }

    // Prepare buffer pool for output frames
    AVFrame* frame = av_frame_alloc();
    if (!frame) {
        // Handle error
        avcodec_free_context(&codec_context);
        return;
    }

    // Check for available buffers and initialize the codec
    // Notify the event handler upon completion
    if (event_handler && event_handler->on_initialization_complete) {
        event_handler->on_initialization_complete(message_loop, context, codec_context);
    }

    av_frame_free(&frame);
}

void FFmpegVideoDecodeEngine_Initialize(MessageLoop* message_loop, VideoDecodeEngine::EventHandler* event_handler, VideoDecodeContext* context, const VideoDecoderConfig& config) {
    AVCodecContext* codec_context = avcodec_alloc_context3(NULL);
    if (!codec_context) {
        // Handle memory allocation error
        return;
    }

    // Configure the codec context based on the provided config
    codec_context->thread_count = 4; // Example threading setup

    // Set up error detection and other codec-specific configurations
    codec_context->flags |= AV_CODEC_FLAG_LOW_DELAY;

    // Prepare buffer pool for output frames
    AVBufferPool* buffer_pool = av_buffer_pool_init(codec_context->width, codec_context->height, NULL);
    if (!buffer_pool) {
        // Handle buffer pool initialization error
        avcodec_free_context(&codec_context);
        return;
    }

    // Initialize the codec
    int result = avcodec_open2(codec_context, NULL, NULL);
    if (result < 0) {
        // Handle codec initialization error
        av_buffer_pool_uninit(&buffer_pool);
        avcodec_free_context(&codec_context);
        return;
    }

    // Notify event handler upon completion
    event_handler->OnInitializationComplete(message_loop, context, codec_context);
}

void FFmpegVideoDecodeEngine_Initialize(MessageLoop* message_loop, VideoDecodeEngine::EventHandler* event_handler, VideoDecodeContext* context, const VideoDecoderConfig& config) {
    AVCodecContext* codec_context = avcodec_alloc_context3(NULL);
    if (!codec_context) {
        // Handle memory allocation failure
        return;
    }

    // Configure codec context based on video_decoder_config
    // (Example configuration - actual parameters may vary)
    codec_context->width = config.width;
    codec_context->height = config.height;
    codec_context->pix_fmt = AV_PIX_FMT_YUV420P;

    // Set up threading for decoding
    codec_context->thread_count = 4;

    // Set up error detection
    codec_context->error_recognition = AV_EF_CRCCheck;

    // Allocate buffer pool for output frames
    AVBufferPool* buffer_pool = av_buffer_pool_init(codec_context->width * codec_context->height * 3 / 2, NULL);
    if (!buffer_pool) {
        avcodec_free_context(&codec_context);
        // Handle buffer pool allocation failure
        return;
    }

    // Apply any codec-specific configurations
    // (This is codec-dependent and may involve setting additional parameters)

    // Check for available buffers and initialize the codec
    int result = avcodec_open2(codec_context, avcodec_find_decoder(codec_context->codec_id), NULL);
    if (result < 0) {
        av_buffer_pool_uninit(&buffer_pool);
        avcodec_free_context(&codec_context);
        // Handle codec initialization failure
        return;
    }

    // Notify event handler upon completion
    event_handler->OnInitializationComplete(codec_context);
}

